module Zocalo.Common.ContentDisposition(mkDispositionHeader) where

import Data.Text.Encoding(encodeUtf8)

import qualified Data.ByteString       as BS
import qualified Data.ByteString.Char8 as BSChar
import qualified Data.Text             as Text


-- Builds an `attachment` Content-Disposition value for any file name (RFC 6266):
--   * `filename`  is an ASCII-only fallback; quotes, backslashes, percent signs, control characters
--                 (including CR/LF), and non-ASCII characters are each replaced with an underscore
--   * `filename*` carries the exact name, UTF-8 and percent-encoded (RFC 5987); clients that understand it
--                 prefer it
mkDispositionHeader :: Text -> ByteString
mkDispositionHeader name =
    BS.concat
      [ "attachment; filename=\""
      , encodeUtf8 asciiName
      , "\"; filename*=UTF-8''"
      , BS.concatMap percentEncode $ encodeUtf8 name
      ]
  where
    asciiName = Text.map (\c -> if isSafe c then c else '_') name
    isSafe c  = c >= ' ' && c <= '~' && c /= '"' && c /= '\\' && c /= '%'

percentEncode :: Word8 -> ByteString
percentEncode w
  | isAttrChar w = BS.singleton w
  | otherwise    = '%' `BSChar.cons` (BS.pack [hexDigit high, hexDigit low])
  where
    (high, low) = w `divMod` 16

-- RFC 5987 `attr-char`: ALPHA / DIGIT / "!" / "#" / "$" / "&" / "+" / "-" / "." / "^" / "_" / "`" / "|" / "~"
isAttrChar :: Word8 -> Bool
isAttrChar w = (w >= 48 && w <= 57) || (w >= 65 && w <= 90) || (w >= 97 && w <= 122) || BS.elem w extras
  where
    extras = BSChar.pack "!#$&+-.^_`|~"

hexDigit :: Word8 -> Word8
hexDigit = fromIntegral &> BS.index "0123456789ABCDEF"
